∀ {L : ℕ} {B eps : ℝ} (sigma : CausalSmith.Stat.AnnotationRarearmFrontier.ConeDual L B eps) (u w : ℝ) (hyp : Bool) (z : CausalSmith.Stat.AnnotationRarearmFrontier.Latent L),
  0 ≤ B / (100 * ↑L ^ 2) →
    0 < eps →
      eps ≤ 1 →
        ∀ (hu : 0 ≤ u) (hw : 0 ≤ w) (huw : 0 < u + w),
          have q := ⟨u / (u + w), CausalSmith.Stat.AnnotationRarearmFrontier.affine_poisson_binomial_split._proof_1 u w hu hw huw⟩;
          have alpha := B / (100 * ↑L ^ 2);
          have s1 := alpha + (1 - eps) * CausalSmith.Stat.AnnotationRarearmFrontier.latentNode sigma z;
          have s0 := (1 - eps) * (alpha / eps) + eps * CausalSmith.Stat.AnnotationRarearmFrontier.latentNode sigma z;
          have mean :=
            match z with
            | none => 0
            | some i => (1 + (if hyp = true then 1 else -1) * CausalSmith.Stat.AnnotationRarearmFrontier.latentPolar sigma (some i)) / 2;
          (CausalSmith.Stat.AnnotationRarearmFrontier.affineCellPoissonLaw sigma u w hyp z).bind ⇑(CausalSmith.Stat.AnnotationRarearmFrontier.affineCellControlSplitKernel q) = ((ProbabilityTheory.poissonMeasure (u * s1 * mean).toNNReal).prod (ProbabilityTheory.poissonMeasure (u * s1 * (1 - mean)).toNNReal)).prod ((ProbabilityTheory.poissonMeasure (w * s1).toNNReal).prod ((ProbabilityTheory.poissonMeasure (u * s0).toNNReal).prod (ProbabilityTheory.poissonMeasure (w * s0).toNNReal)))

